//! Game bindings for native route contact; shared route storage stays separate.
use super::{Actor,Context,AttackWorld,VehicleWorld,goal};
use crate::{Game,Unit,original_combat,original_route_pool::Pool,original_orders_game::Event};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate) enum Boundary{RoadAssembly(crate::original_route_pool::road::Boundary),MissingActor,MissingMember,MissingGroup(i16),MissingUnit(usize),MissingObject(u8),MissingSavedClass,MissingTerrain(i16),MissingNode(u32),MissingPointState,MissingHardwareProfile,MissingCollisionMask(u32),HardwareTerrainOccupancy,HardwareRepairState(usize),UnitPreamble(usize,u8),RetiredUnitPreamble(usize)}
fn point(u:&Unit)->[i16;2]{[if u.native_transport.as_ref().is_some_and(|t|t.phase==crate::original_transport::Phase::Inside){10000}else{(u.x/2.).floor()as i16},(u.y/2.).floor()as i16]}
impl Game{
 fn native_path_contact_actor(&self,index:usize,read_saved:bool)->Result<Actor,Boundary>{let u=self.units.get(index).ok_or(Boundary::MissingActor)?;let slot=u.native_slot.ok_or(Boundary::MissingActor)?;let m=self.native_group_rosters.members[slot].as_ref().ok_or(Boundary::MissingMember)?;let family=original_combat::animation_family(&u.kind);let saved_class=if read_saved&&family==32{self.native_selection.contexts[slot].saved_class8e.ok_or(Boundary::MissingSavedClass)?}else{0};Ok(Actor{slot:slot as u8,position:point(u),family,class:u.native_class7c,saved_class,role:m.role,flags31:m.flags31,flags71:u.native_initiative_scan.flags71,grenades:u.grenades as u8,facing:original_combat::facing(u.angle),counter67:u.native_counter67,directiona2:u.native_directiona2,step62:u.native_field62})}
 pub(crate) fn prepare_native_path_contacts(&mut self){if !self.map.original{return;}let actors=(0..240).filter_map(|slot|{let u=self.units.iter().rfind(|u|u.native_slot==Some(slot))?;let m=self.native_group_rosters.members[slot].as_ref()?;Some(Actor{slot:slot as u8,position:point(u),class:u.native_class7c,flags31:m.flags31,flags71:u.native_initiative_scan.flags71,..Default::default()})}).collect::<Vec<_>>();self.native_path_contact.prepare(actors);}
 fn native_contact_terrain(&self,cell:i16)->Result<u8,Boundary>{if !(0..16384).contains(&cell){return Err(Boundary::MissingTerrain(cell));}let cell=cell as usize;let(x,y)=(cell&127,cell>>7);if x<self.map.width&&y<self.map.height{self.map.terrain_codes.get(y*self.map.width+x).copied()}else{self.map.native_terrain_plane.get(cell).copied()}.ok_or(Boundary::MissingTerrain(cell as i16))}
 ///51330 gets its goal lazily. The route worker may own a detached Pool;
 ///the closure supplies that exact pool instead of an empty Game scratch.
 pub(crate) fn native_autoattack_contact(&mut self,index:usize,context:Context,mut goal:impl FnMut(&mut Game,usize)->Result<[i16;2],Boundary>)->Result<bool,Boundary>{let mut actor=self.native_path_contact_actor(index,true)?;let mut state=std::mem::take(&mut self.native_path_contact);let mut env=AttackEnv{game:self,index,goal:&mut goal};let result=super::auto_attack(&mut actor,&mut state,context,&mut env);env.game.units[index].grenades=usize::from(actor.grenades);env.game.native_path_contact=state;result}
 ///51700 writes the actual attempted point back through Context.proposed.
 pub(crate) fn native_vehicle_goal(&mut self,index:usize,context:&mut Context)->Result<bool,Boundary>{let mut actor=self.native_path_contact_actor(index,false)?;let mut state=std::mem::take(&mut self.native_path_contact);let mut env=VehicleEnv{game:self,error:None};let result=super::vehicle_goal(&mut actor,&mut state,context,&mut env);let error=env.error;env.game.units[index].native_counter67=actor.counter67;env.game.units[index].native_directiona2=actor.directiona2;env.game.units[index].angle=crate::native_math::angle(actor.facing);env.game.native_path_contact=state;if let Some(error)=error{Err(error)}else{Ok(result)}}
 pub(crate) fn native_contact_goal(&mut self,index:usize,pool:&Pool)->Result<goal::Goal,Boundary>{let u=self.units.get(index).ok_or(Boundary::MissingActor)?.clone();let slot=u.native_slot.ok_or(Boundary::MissingActor)?;let m=self.native_group_rosters.members[slot].as_ref().ok_or(Boundary::MissingMember)?;let mut input=goal::Input{slot:slot as u8,position:point(&u),class:u.native_class7c,role:m.role,group:m.group,flags31:m.flags31,flags8a:m.flags8a,flags64:u.native_flags64,flags9c:u.native_flags9c,object36:m.reserved_object.unwrap_or(0)as u8,contact5d:m.contact_order,target50:m.promotion.target_x,point54:[m.promotion.target_y,m.promotion.target_aux],primary:pool.links[slot].primary};let mut env=GoalEnv{game:self,pool,input};let result=goal::resolve(&mut input,&mut env);if let Some(m)=env.game.native_group_rosters.members[slot].as_mut(){m.flags31=input.flags31;m.contact_order=input.contact5d;}result}
}
struct AttackEnv<'a,F>{game:&'a mut Game,index:usize,goal:&'a mut F}
impl<F:FnMut(&mut Game,usize)->Result<[i16;2],Boundary>>AttackWorld for AttackEnv<'_,F>{type Error=Boundary;
 fn donor(&mut self)->Result<Option<u8>,Boundary>{let u=&self.game.units[self.index];let m=self.game.native_group_rosters.members[u.native_slot.unwrap()].as_ref().ok_or(Boundary::MissingMember)?;let row=self.game.native_group_rosters.pool.get(usize::from(m.group)).ok_or(Boundary::MissingGroup(i16::from(m.group)))?;for role in 0..21{let Some(slot)=row.member(role)else{continue;};let u=self.game.units.iter().rfind(|u|u.native_slot==Some(usize::from(slot))).ok_or(Boundary::MissingUnit(usize::from(slot)))?;if u.grenades as u8!=0{return Ok(Some(slot));}}Ok(None)}
 fn donate(&mut self,slot:u8){if let Some(u)=self.game.units.iter_mut().rfind(|u|u.native_slot==Some(usize::from(slot))){u.grenades=usize::from((u.grenades as u8).wrapping_sub(1));}}
 fn terrain(&mut self,cell:i16)->Result<u8,Boundary>{self.game.native_contact_terrain(cell)}
 fn goal(&mut self)->Result<[i16;2],Boundary>{(self.goal)(self.game,self.index)}
 fn random(&mut self)->u32{self.game.native_random()}
 fn attack(&mut self,point:[i16;2]){let metadata=self.game.native_order_arguments[2];self.game.record_native_order_event(self.index,Event::classified(12,point,metadata));}
}
struct VehicleEnv<'a>{game:&'a mut Game,error:Option<Boundary>}
impl VehicleWorld for VehicleEnv<'_>{fn terrain(&mut self,c:i16)->u8{match self.game.native_contact_terrain(c){Ok(n)=>n,Err(e)=>{self.error.get_or_insert(e);0}}}fn vehicle(&mut self,slot:u8)->([i16;2],u8){let owner=self.game.native_group_rosters.members.get(usize::from(slot)).and_then(Option::as_ref).map_or(0,|m|m.flags31&3);if let Some(p)=self.game.native_raw_unit_position(usize::from(slot)){(p,owner)}else{self.error.get_or_insert(Boundary::MissingUnit(usize::from(slot)));([0;2],owner)}}}
struct GoalEnv<'a>{game:&'a mut Game,pool:&'a Pool,input:goal::Input}
impl GoalEnv<'_>{fn raw_unit(&mut self,slot:usize)->Result<[i16;2],Boundary>{let n=u8::try_from(slot).map_err(|_|Boundary::MissingUnit(slot))?;self.game.native_raw_unit_position(usize::from(n)).ok_or(Boundary::MissingUnit(slot))}}
impl goal::World for GoalEnv<'_>{type Error=Boundary;
 fn object(&mut self,slot:u8)->Result<[i16;2],Boundary>{self.game.native_object_raw_position(slot).ok_or(Boundary::MissingObject(slot))}
 fn leader(&mut self,group:usize)->Result<u8,Boundary>{self.game.native_group_rosters.pool.get(group).map(|g|g.roster[19]).ok_or(Boundary::MissingGroup(group as i16))}
 fn unit(&mut self,slot:usize)->Result<[i16;2],Boundary>{self.raw_unit(slot)}
 fn nearest_group_member(&mut self,group:i16)->Result<Option<[i16;2]>,Boundary>{let row=self.game.native_group_rosters.pool.get(group as u16 as usize).ok_or(Boundary::MissingGroup(group))?;let slots=row.roster[19..40].to_vec();let mut nearest=None;let mut best=i32::MAX;let own=self.input.slot;for slot in slots.into_iter().filter(|&s|s!=255&&s!=own){let flags=self.game.native_group_rosters.members.get(usize::from(slot)).and_then(Option::as_ref).map_or(0,|m|m.flags31);if flags&4==0{continue;}let p=self.raw_unit(usize::from(slot))?;let dx=i32::from(p[0])-i32::from(self.input.position[0]);let dy=i32::from(p[1])-i32::from(self.input.position[1]);let d=dx.wrapping_mul(dx).wrapping_add(dy.wrapping_mul(dy));if d<best{best=d;nearest=Some(p);}}Ok(nearest)}
 fn target(&mut self)->Result<Option<[i16;2]>,Boundary>{let input=self.input;let target=if input.class==1{match input.target50{-1234=>{if matches!(input.point54[0],-1|255){return Ok(None);}let group=input.point54[0];if group<0{return Err(Boundary::MissingGroup(group));}usize::from(self.leader(group as usize)?)},-4321=>input.point54[0]as u16 as usize,_=>return Ok(None)}}else if input.target50<0{let group=i16::from(input.target50.wrapping_neg()as u8)-1;if group<0{return Err(Boundary::MissingGroup(group));}let leader=self.leader(group as usize)?;if leader==255{return Ok(None);}usize::from(leader)}else{if input.target50==3456{return Ok(None);}usize::from(input.target50 as u8)};if target>=240{return Err(Boundary::MissingUnit(target));}let flags=self.game.native_group_rosters.members[target].as_ref().map_or(0,|m|m.flags31);let protection=self.game.units.iter().rfind(|u|u.native_slot==Some(target)).map_or(0,|u|u.native_protectionaa);if !crate::original_orders_game::valid_live_target(input.flags31,flags,protection){return Ok(None);}self.raw_unit(target).map(Some)}
 fn node(&mut self,link:u32)->Result<[i16;2],Boundary>{self.pool.node(link).map(|n|n.point).ok_or(Boundary::MissingNode(link))}
}
#[cfg(test)]mod tests{
 use super::*;
 fn field()->Game{let mut g=Game::new(0,1,51330);g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.native_group_rosters.clear();g.native_ambient=None;g.native_path_contact=Default::default();g.spawn("grunt",0,640.,640.,1,None);g.spawn("grunt",0,672.,640.,1,None);g.spawn("medium",1,1000.,1000.,2,None);g.maintain_native_group_rosters();g}
 fn context()->Context{Context{blocked:[20*128+20,-1],proposed:[350,360],force:false,callback_idle:true,current_actor:false,dummy_actor:false}}
 #[test]fn nearby_destructible_uses_a_real_group_grenade_and_raw_personal_command_twelve(){let mut g=field();g.units[0].grenades=0;g.units[1].grenades=3;g.map.terrain_codes[20*64+20]=1;g.native_order_arguments[2]=-789;let slot=g.units[0].native_slot.unwrap();let group=usize::from(g.native_group_rosters.members[slot].as_ref().unwrap().group);g.native_group_rosters.pool[group].roster[58]=1;g.native_group_rosters.members[slot].as_mut().unwrap().flags69=56;let mut rng=g.original_rng.clone();let x=320+((rng.next_u32()&15)as i16)-8;let y=320+((rng.next_u32()&15)as i16)-8;assert_eq!(g.native_autoattack_contact(0,context(),|_,_|panic!("class0 skips43bdd0")),Ok(true));assert_eq!((g.units[0].grenades,g.units[1].grenades),(1,2));assert_eq!(g.units[0].native_order5c,12);let m=g.native_group_rosters.members[slot].as_ref().unwrap();assert_eq!((m.promotion.target_x,m.promotion.target_y,m.promotion.target_aux),(i32::from(x),y,-789));assert_eq!(m.flags69,32);assert_eq!(g.native_group_rosters.pool[group].roster[58],1);assert_eq!(g.original_rng.words,rng.words);assert!(g.native_path_contact.donated);}
 #[test]fn failed_terrain_admission_keeps_earlier_grenade_donation_without_spending_rng(){let mut g=field();g.units[0].grenades=0;g.units[1].grenades=1;let rng=g.original_rng.words;assert_eq!(g.native_autoattack_contact(0,context(),|_,_|panic!()),Ok(false));assert_eq!((g.units[0].grenades,g.units[1].grenades),(1,0));assert_eq!(g.original_rng.words,rng);assert!(g.native_path_contact.donated);assert_eq!(g.units[0].native_order5c,0);}
 #[test]fn goal_read_failure_is_an_explicit_boundary_before_rng_or_command_mutation(){let mut g=field();g.units[0].native_class7c=2;g.map.terrain_codes[20*64+20]=1;let rng=g.original_rng.words;assert_eq!(g.native_autoattack_contact(0,context(),|_,_|Err(Boundary::MissingNode(17))),Err(Boundary::MissingNode(17)));assert_eq!(g.original_rng.words,rng);assert_eq!(g.units[0].native_order5c,0);}
 #[test]fn vehicle_membership_is_frozen_before_units_but_queries_read_updated_positions_and_owner(){let mut g=field();g.units[0].kind="medium".into();g.units[0].native_class7c=1;g.prepare_native_path_contacts();assert_eq!(g.native_path_contact.vehicles.len(),2);g.units[2].x=700.;g.units[2].y=720.;g.units[2].hp=-1.;g.units[2].native_class7c=0;let target=g.units[2].native_slot.unwrap();g.native_group_rosters.members[target].as_mut().unwrap().flags31&=!4;let mut c=context();c.blocked=[-1,-1];assert_eq!(g.native_vehicle_goal(0,&mut c),Ok(true));assert_eq!(c.proposed,[320,320]);assert_eq!(g.native_path_contact.collision,Some(1));assert_eq!(g.native_path_contact.vehicles[1].position,[350,360]);assert_eq!(g.units[0].native_counter67,8);}
 #[test]fn contact_goal_reads_real_pool_and_personal_ground_point_with_distinct_node_outputs(){let mut g=field();let slot=g.units[0].native_slot.unwrap();let m=g.native_group_rosters.members[slot].as_mut().unwrap();m.role=0;m.flags31=4|64;m.flags8a=4;let mut pool=Pool::default();let link=pool.allocate_goal([777,-555]).unwrap();pool.links[slot].primary=link;let out=g.native_contact_goal(0,&pool).unwrap();assert_eq!((out.position,out.node,out.failed),([777,-555],link,false));pool.links[slot].primary=0;assert!(g.native_contact_goal(0,&pool).unwrap().failed);assert_eq!(g.native_group_rosters.members[slot].as_ref().unwrap().flags31&64,0);let m=g.native_group_rosters.members[slot].as_mut().unwrap();m.flags8a=0;m.promotion.target_x=3456;m.promotion.target_y=999;m.promotion.target_aux=-777;g.units[0].native_flags64|=8;let out=g.native_contact_goal(0,&pool).unwrap();assert_eq!((out.position,out.node,out.failed),([999,-777],u32::MAX,false));g.units[0].native_flags9c|=128;assert_eq!(g.native_contact_goal(0,&pool).unwrap().node,0);}
}
